-- DATOS SEMILLA: 10 RAMAS Y 82 SUBCATEGORÍAS (ANEXO A)
-- ==============================================================================
-- Instrucciones:
-- 1. Ve a tu proyecto en Supabase (https://supabase.com/dashboard).
-- 2. Entra en "SQL Editor", crea una "New Query", pega este contenido y pulsa "Run".
-- ==============================================================================

ON CONFLICT (slug) DO UPDATE SET
  rama_id = EXCLUDED.rama_id,
  rama_nombre = EXCLUDED.rama_nombre,
  grupo = EXCLUDED.grupo,
  nombre = EXCLUDED.nombre,
  actores = EXCLUDED.actores,
  orden = EXCLUDED.orden;
